<div class="d-flex justify-content-between align-items-center mb-3"><div><h4>Pendaftaran</h4><p class="text-muted small">Data tersimpan tanpa memuat ulang halaman.</p></div><button class="btn btn-primary" id="addBtn">+ Tambah Pendaftar</button></div><div id="alert-container"></div><div class="card"><div class="card-header d-flex justify-content-between"><strong>Daftar Pendaftar <span class="badge text-bg-light" id="total-count">0</span></strong><input type="search" id="search" class="form-control" style="max-width:260px" placeholder="Cari pendaftar..."></div><div class="table-responsive"><table class="table table-hover mb-0" id="pendaftaran-table"><thead><tr><th>No</th><th>Nama</th><th>Asal Sekolah</th><th>Prodi Tujuan</th><th>Kontak</th><th>Berkas</th><th>Aksi</th></tr></thead><tbody><tr><td colspan="7" class="text-center p-4">Memuat data...</td></tr></tbody></table></div></div>
<div class="modal fade" id="pendaftaranModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 id="pendaftaranModalLabel">Tambah Pendaftar</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><form id="pendaftaranForm">@csrf<input type="hidden" id="id" name="id">@foreach(['nama'=>'Nama Lengkap','asal_sekolah'=>'Asal Sekolah','prodi_tujuan'=>'Prodi Tujuan','email'=>'Email','no_hp'=>'No HP'] as $key=>$label)<div class="mb-3"><label class="form-label" for="{{ $key }}">{{ $label }} *</label><input class="form-control" id="{{ $key }}" name="{{ $key }}" type="{{ $key==='email'?'email':'text' }}" required><div class="invalid-feedback" id="{{ $key }}-error"></div></div>@endforeach<div class="mb-3"><label class="form-label">Berkas Pendukung <span id="berkas-required">*</span></label><div id="berkas-current" class="small d-none mb-2">Berkas saat ini: <a id="berkas-current-link" target="_blank"></a></div><input type="file" class="form-control" id="berkas" name="berkas" accept=".jpg,.jpeg,.png,.pdf"><div class="invalid-feedback" id="berkas-error"></div><small class="text-muted" id="berkas-help">JPG, JPEG, PNG, PDF; maksimal 2 MB.</small></div></form></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary" id="saveBtn">Simpan</button></div></div></div></div>
@endsection
@push('scripts')<script>
$(function(){const urls={data:@json(route('pendaftaran.data')),store:@json(route('pendaftaran.store')),edit:@json(route('pendaftaran.edit',':id')),update:@json(route('pendaftaran.update',':id')),destroy:@json(route('pendaftaran.destroy',':id'))};let records=[];$.ajaxSetup({headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content'),'Accept':'application/json'}});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function alertMsg(msg,type='success'){$('#alert-container').html(`<div class="alert alert-${type} alert-dismissible">${esc(msg)}<button class="btn-close" data-bs-dismiss="alert"></button></div>`)}
function errorsClear(){$('#pendaftaranForm .is-invalid').removeClass('is-invalid');$('#pendaftaranForm .invalid-feedback').text('')}
function setFile(item=null){$('#berkas').val('');$('#berkas-required').toggleClass('d-none',!!item);$('#berkas-current').toggleClass('d-none',!item?.berkas_url);$('#berkas-help').text(item?'Kosongkan jika tidak ingin mengganti berkas. Maksimal 2 MB.':'JPG, JPEG, PNG, PDF; maksimal 2 MB.');if(item?.berkas_url)$('#berkas-current-link').attr('href',item.berkas_url).text(item.nama_berkas||'Lihat berkas')}
function render(){let k=$('#search').val().toLowerCase();let rows=records.filter(x=>[x.nama,x.asal_sekolah,x.prodi_tujuan,x.email,x.no_hp].some(v=>String(v).toLowerCase().includes(k)));$('#total-count').text(rows.length);if(!rows.length){$('#pendaftaran-table tbody').html('<tr><td colspan="7" class="text-center p-4 text-muted">Belum ada data yang cocok.</td></tr>');return;}$('#pendaftaran-table tbody').html(rows.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.nama)}</td><td>${esc(x.asal_sekolah)}</td><td>${esc(x.prodi_tujuan)}</td><td>${esc(x.email)}<br>${esc(x.no_hp)}</td><td>${x.berkas_url?`<a target="_blank" rel="noopener" href="${esc(x.berkas_url)}">${esc(x.nama_berkas||'Lihat berkas')}</a>`:'-'}</td><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary edit" data-id="${x.id}">Edit</button> <button class="btn btn-sm btn-outline-danger delete" data-id="${x.id}" data-nama="${esc(x.nama)}">Hapus</button></td></tr>`).join(''))}
function load(){ $.getJSON(urls.data).done(d=>{records=d;render()}).fail(()=>alertMsg('Gagal memuat data.','danger'))}load();$('#search').on('input',render);const modal=bootstrap.Modal.getOrCreateInstance('#pendaftaranModal');
$('#addBtn').on('click',()=>{$('#pendaftaranForm')[0].reset();$('#id').val('');errorsClear();setFile();$('#pendaftaranModalLabel').text('Tambah Pendaftar');modal.show()});$('#pendaftaranModal').on('hidden.bs.modal',()=>{$('#pendaftaranForm')[0].reset();$('#id').val('');errorsClear();setFile()});
$('#saveBtn').on('click',function(){let id=$('#id').val(),fd=new FormData($('#pendaftaranForm')[0]);if(id)fd.append('_method','PUT');errorsClear();let b=$(this).prop('disabled',true).text('Menyimpan...');$.ajax({url:id?urls.update.replace(':id',id):urls.store,type:'POST',data:fd,processData:false,contentType:false,dataType:'json'}).done(r=>{modal.hide();load();alertMsg(r.success)}).fail(xhr=>{if(xhr.status===422){$.each(xhr.responseJSON.errors,(k,v)=>{$('#'+k).addClass('is-invalid');$('#'+k+'-error').text(v[0])})}else alertMsg('Terjadi kesalahan saat menyimpan data.','danger')}).always(()=>b.prop('disabled',false).text('Simpan'))});
$(document).on('click','.edit',function(){let id=$(this).data('id');$.getJSON(urls.edit.replace(':id',id)).done(d=>{$('#id').val(d.id);['nama','asal_sekolah','prodi_tujuan','email','no_hp'].forEach(k=>$('#'+k).val(d[k]));setFile(d);$('#pendaftaranModalLabel').text('Edit Pendaftar');modal.show()}).fail(()=>alertMsg('Gagal memuat data.','danger'))});
$(document).on('click','.delete',function(){let id=$(this).data('id'),nama=$(this).data('nama');confirmDelete(`Data pendaftar "${nama}" akan dihapus?`).then(ok=>{if(ok)$.ajax({url:urls.destroy.replace(':id',id),type:'DELETE',dataType:'json'}).done(r=>{load();alertMsg(r.success)}).fail(()=>alertMsg('Gagal menghapus data.','danger'))})});
});</script>@endpush
